1: import { AgentContext, type AgentContextSnapshot } from '../agents/agentContext';
2: import { sourceFileHash, type AgentContextSourceFile, type AgentContextSourceRange } from '../agents/agentContextSource';
3: import { sha256 } from '../sha256';
4: import type { Diagram } from './diagram';
