6: export interface DiagramAgentContextStore {
7:   put(snapshot: AgentContextSnapshot): Promise<string>;
8:   get(recordId: string): Promise<unknown>;
9:   portable?(snapshot: AgentContextSnapshot): Promise<AgentContextSnapshot>;
10:   resolve?(snapshot: AgentContextSnapshot): Promise<AgentContextSnapshot>;
11: }
12: 
13: interface DiagramAgentContextIdentity {
14:   diagramId: string;
15:   compiledFromRevisionId: string;
16:   sourceFingerprint: string;
17: }
18: 
19: export type StoredDiagramAgentContext = DiagramAgentContextIdentity & {
20:   backingRecordId: string; contentHash: string; snapshot?: never;
21: };
22: export type InlineDiagramAgentContext = DiagramAgentContextIdentity & {
23:   snapshot: AgentContextSnapshot; contentHash?: string; backingRecordId?: never;
24: };
25: /** The diagram carries a small disk reference. Inline snapshots remain valid for old workspaces and portable exports. */
26: export type DiagramAgentContext = StoredDiagramAgentContext | InlineDiagramAgentContext;
27: 
28: export function diagramContextSourceFingerprint(diagram: Diagram): string {
29:   return sha256(JSON.stringify({ binding: diagram.sourceContext.binding ?? null, evidence: diagram.sourceContext.evidence }));
30: }
31: 
32: /** Capture stable source evidence once; the current diagram is supplied by each later generation request. */
33: export function compileDiagramAgentContext(diagram: Diagram): InlineDiagramAgentContext {
34:   const sourceFingerprint = diagramContextSourceFingerprint(diagram);
35:   const sourceFiles: Record<string, AgentContextSourceFile> = {};
36:   const references: AgentContextSourceRange[] = [];
37:   const evidence = Object.fromEntries(Object.entries(diagram.sourceContext.evidence).map(([id, entry]) => [id, {
38:     ...entry, sourceRanges: entry.sourceRanges.map(({ originalLines, ...range }) => {
39:       const file = { startLine: range.startLine, lines: [...originalLines] }, contentHash = sourceFileHash(file);
40:       sourceFiles[contentHash] = file;
41:       const reference: AgentContextSourceRange = { type: 'sourceRange', sourceId: entry.sourceId ?? diagram.sourceContext.binding?.sourceId ?? diagram.diagramId,
42:         path: range.path, startLine: range.startLine, endLine: range.endLine, version: { kind: 'snapshot', contentHash } };
43:       references.push(reference);
44:       return { ...range, source: reference };
45:     })
46:   }]));
47:   const context = AgentContext.fromTrajectory({ agentType: 'diagram-context', sourceSessionId: diagram.diagramId,
48:     format: 'messages-v1', fromEntryId: 'source', throughEntryId: 'source', entries: [{ id: 'source', parentId: null,
49:       message: { role: 'user', timestamp: 0, content: [{ type: 'text', text: `Source evidence for diagram ${diagram.diagramId}. This is background captured at revision ${diagram.revisionId}; use the current diagram supplied with each edit request as the authoritative content.\n${JSON.stringify({ binding: diagram.sourceContext.binding ?? null, evidence })}` }, ...references] } }] });
50:   return { diagramId: diagram.diagramId, compiledFromRevisionId: diagram.revisionId, sourceFingerprint,
51:     contentHash: context.contentHash, snapshot: AgentContext.fromSnapshot({ ...context.toSnapshot(), ...(references.length ? { sourceFiles } : {}) }).toSnapshot() };
52: }
53: 
54: export async function storeDiagramAgentContext(value: DiagramAgentContext, store: DiagramAgentContextStore): Promise<StoredDiagramAgentContext> {
55:   validateDiagramAgentContext(value);
56:   if (!value.snapshot) return value as StoredDiagramAgentContext;
57:   const backingRecordId = await store.put(value.snapshot);
58:   if (!/^[a-f0-9]{64}$/.test(backingRecordId)) throw Error('Invalid diagram context backing record');
59:   return { diagramId: value.diagramId, compiledFromRevisionId: value.compiledFromRevisionId,
60:     sourceFingerprint: value.sourceFingerprint, contentHash: value.snapshot.contentHash, backingRecordId };
61: }
62: 
63: export async function loadDiagramAgentContext(value: DiagramAgentContext, store?: DiagramAgentContextStore): Promise<AgentContextSnapshot> {
64:   validateDiagramAgentContext(value);
65:   const raw = value.snapshot ?? (store && value.backingRecordId ? await store.get(value.backingRecordId) : undefined);
66:   if (!raw) throw Error('AGENT_CONTEXT_STORAGE_UNAVAILABLE: diagram context backing record cannot be loaded');
67:   const snapshot = AgentContext.fromSnapshot(raw).toSnapshot();
68:   if ((value.contentHash && snapshot.contentHash !== value.contentHash) || snapshot.source.agentType !== 'diagram-context'
69:     || snapshot.source.sourceSessionId !== value.diagramId) throw Error('DIAGRAM_CONTEXT_MISMATCH: backing record does not match diagram');
70:   return snapshot;
71: }
